/**
 * ComplianceCheck defines a Compliance Check.
 */
export type ComplianceCheck = {
    /**
     * AzurePolicyID is the ID of the Azure Policy that this compliance check represents. Only present for
     * Azure Policy compliance checks.
     */
    azure_policy_id?: number | null;
    /**
     * TODO: add a valid example here
     * Body of the Compliance Check defining what actions will be run.
     */
    body?: string;
    /**
     * CloudProviderID for the Compliance Check in the application.
     * 1 - AWS.
     * 2 - Microsoft.
     */
    cloud_provider_id?: number | null;
    /**
     * ComplianceCheckTypeID for the Compliance Check in the application.
     * 1 - External. These checks are not triggered by cloudtamer.io, but rather can display findings from checks run outside of cloudtamer.io.
     * 2 - Cloud Custodian. These checks are run by cloudtamer.io using Cloud Custodian.
     * 3 - Azure Policy. These checks are scraped from Azure's policy reporting engine and apply Azure Policies to accounts.
     */
    compliance_check_type_id?: number | null;
    /**
     * Date when the Compliance Check was added to the application.
     */
    created_at?: string;
    /**
     * CreatedByUserID refers to the User in the application who created the Compliance Check
     */
    created_by_user_id?: number | null;
    /**
     * Managed signifies that this compliance check is managed by cloudtamer.io
     */
    ct_managed?: boolean | null;
    /**
     * SeverityTypeID for the severity level of the compliance check
     * 1 - Informational.
     * 2 - Low.
     * 3 - Medium (Default).
     * 4 - High.
     */
    default_severity_type_id?: number | null;
    /**
     * Description for the Compliance Check in the application.
     */
    description?: string;
    /**
     * FrequencyMinutes defines how often the check will be run.
     */
    frequency_minutes?: number;
    /**
     * FrequencyTypeID refers to the duration type of the frequency it will be checked
     * 2 - minutes
     * 3 - hours
     * 4 - days
     */
    frequency_type_id?: number | null;
    /**
     * ID of the compliance check in the application.
     */
    id?: number;
    /**
     * IsAllRegions determines if the check should be applied to all regions applied on the system
     */
    is_all_regions?: boolean | null;
    /**
     * IsAutoArchived defines whether existing findings should be archived before new findings are reported.
     */
    is_auto_archived?: boolean | null;
    /**
     * LastScanID defines the latest scan id
     */
    last_scan_id?: number | null;
    /**
     * Name of the Compliance Check in the application.
     */
    name?: string;
    /**
     * List of the AWS regions where the compliance check applies
     */
    regions: Array<string> | null;
    /**
     * DefaultSeverityTypeID default recommended severity level of the compliance check
     * 1 - Informational.
     * 2 - Low.
     * 3 - Medium.
     * 4 - High.
     * 5 - Critical
     */
    severity_type_id?: number | null;
};

/**
 * ComplianceCheckCreate defines a Compliance Check creation.
 */
export type ComplianceCheckCreate = {
    /**
     * AzurePolicyID refers to the ID of the Azure Policy in cloudtamer.io which will be deployed and scraped to determine
     * compliance status of Azure resources. Should only be provided for Azure Policy checks.
     */
    azure_policy_id?: number | null;
    /**
     * TODO: add a valid example here
     * Body of the Compliance Check defining what actions will be run.
     */
    body?: string;
    /**
     * CloudProviderID for the Compliance Check in the application. Must be "2" for Azure Policy checks.
     * 1 - AWS.
     * 2 - Microsoft.
     */
    cloud_provider_id: number | null;
    /**
     * ComplianceCheckTypeID for the Compliance Check in the application.
     * 1 - External. These checks are not triggered by cloudtamer.io, but rather can display findings from checks run outside of cloudtamer.io.
     * 2 - Cloud Custodian. These checks are run by cloudtamer.io using Cloud Custodian.
     * 3 - Azure Policy. These checks are scraped from Azure's policy reporting engine and apply Azure Policies to accounts.
     */
    compliance_check_type_id: number | null;
    /**
     * List of Compliance Control IDs to which this Compliance Check is linked.
     */
    compliance_control_ids?: Array<number> | null;
    /**
     * ComplianceStandardID is an optional field for which compliance standard the created check should be associated with.
     */
    compliance_standard_id?: number | null;
    /**
     * CreatedByUserID refers to the User in the application who created the Compliance Check. Will be the requesting User's ID if not specified.
     */
    created_by_user_id?: number | null;
    /**
     * Description for the Compliance Check in the application.
     */
    description?: string;
    /**
     * FrequencyMinutes defines how often the check will be run. Is required if check type is Cloud Custodian or Azure Policy.
     */
    frequency_minutes?: number;
    /**
     * FrequencyTypeID refers to the duration type of the frequency it will be checked. Is required if check type is Cloud Custodian or Azure Policy.
     * 2 - minutes
     * 3 - hours
     * 4 - days
     */
    frequency_type_id?: number | null;
    /**
     * IsAllRegions determines if the check should be applied to all regions applied on the system
     */
    is_all_regions?: boolean | null;
    /**
     * IsAutoArchived defines whether existing findings should be archived before new findings are reported.
     */
    is_auto_archived?: boolean | null;
    /**
     * Name of the Compliance Check in the application.
     */
    name: string;
    /**
     * List of groups IDs who will own the Compliance Check. Is required if no owner user IDs are listed.
     */
    owner_user_group_ids?: Array<number> | null;
    /**
     * List of user IDs who will own the Compliance Check. Is required if no owner group IDs are listed.
     */
    owner_user_ids?: Array<number> | null;
    /**
     * List of the AWS regions where the compliance check applies. Required when check type id is cloud custodian.
     */
    regions?: Array<string> | null;
    /**
     * SeverityTypeID for the severity level of the compliance check
     * 1 - Informational.
     * 2 - Low.
     * 3 - Medium (Default).
     * 4 - High.
     */
    severity_type_id?: number | null;
};

