/**
 * GlobalCustomVariableCreate represents the fields necessary to create a custom variable.
 */
export type GlobalCustomVariableCreate = {
    /**
     * DefaultValue is the global default value of the custom variable. Some examples can be found below.
     *
     * For the string type: "Example default value"
     *
     * For the list type: ["example", "example2"]
     *
     * For the map type: {"key": "value", "key2": "value2"}
     */
    default_value?: unknown;
    /**
     * Description is the description of the custom variable. The description can be up to 1024 characters.
     */
    description?: string;
    /**
     * KeyValidationMessage is the message displayed when the custom variable key(s) do not match the regular expression.
     * The key validation message can be up to 255 characters.
     */
    key_validation_message?: string;
    /**
     * KeyValidationRegex is the regular expression used to validate the custom variable key(s) within the map custom
     * variable type. The key validation regex can be up to 255 characters.
     */
    key_validation_regex?: string;
    /**
     * Name is the name of the custom variable. The name can be up to 255 characters.
     */
    name?: string;
    /**
     * OwnerUGroupIDs is the list of user group IDs who will own the custom variable.
     */
    owner_user_group_ids?: Array<number> | null;
    /**
     * OwnerUserIDs is the list of user IDs who will own the custom variable.
     */
    owner_user_ids?: Array<number> | null;
    /**
     * Type is the type of the custom variable. The supported types are string, list, and map.
     */
    type?: string;
    /**
     * ValueValidationMessage is the message displayed when the custom variable value(s) do not match the regular expression.
     * The validation message can be up to 255 characters.
     */
    value_validation_message?: string;
    /**
     * ValueValidationRegex is the regular expression used to validate the custom variable value(s).
     * The validation regex can be up to 255 characters.
     */
    value_validation_regex?: string;
};

