/**
 * OUEnforcement is an enforcement at the OU level.
 */
export type OuEnforcement = {
    cloud_rule?: CloudRule;
    /**
     * Optional, user-provided description of the enforcement.
     */
    description?: string;
    /**
     * Flag that specifies if the enforcement is enabled.
     */
    enabled?: boolean | null;
    /**
     * ID of the record in the application.
     */
    id?: number;
    /**
     * Flag that specifies if enforcement will place project in a overburn state when triggered.
     */
    overburn?: boolean | null;
    service?: Service;
    /**
     * Threshold value. Either a dollar amount or percent based on threshold type.
     */
    threshold?: number;
    /**
     * The type of the threshold value.
     * Valid values are "dollar", "percent".
     */
    threshold_type?: string;
    /**
     * Timeframe of the enforcement.
     * Valid values are "lifetime", "month", "year"
     */
    timeframe?: string;
    /**
     * For OU percent enforcements, controls whether percentage is calculated against an aggregate budget or active threshold when applicable.
     */
    trigger_planned_amount_type?: string;
    /**
     * Flag that specifies if the enforcement is currently triggered.
     */
    triggered?: boolean | null;
    /**
     * List of user group IDs that will receive notifications from the enforcement.
     */
    ugroup_ids?: Array<number> | null;
    /**
     * List of user IDs that will receive notifications from the enforcement.
     */
    user_ids?: Array<number> | null;
};

